#[test]
fn const_init_rejects_non_const_ascriptions_and_shadowed_conversions_e6003() { for src in ["const a any = 1\nfn main() {}\n", "const a option[int] = 1\nfn main() {}\n", "const int8 = 1\nconst x = int8(42)\nfn main() {}\n", "fn main() {\n    const a option[int] = some(1)\n    const b = a\n}\n"] { let r = hy_check::check_file(&hy_syntax::parse_file("t.hy", src).unwrap()); assert!(r.diagnostics.iter().filter(|d| d.code == "HYB-E6003").count() >= if src.contains("const b = a") { 2 } else { 1 }, "{src}: {:?}", r.diagnostics); } assert!(hy_check::check_file(&hy_syntax::parse_file("t.hy", "const a int = int(42)\nfn main() {}\n").unwrap()).diagnostics.is_empty()); }
